import{_ as e,o as r,c as a,a5 as d}from"./chunks/framework.bIR-4glx.js";const b=JSON.parse('{"title":"Vocabulary Evidence Card: From Card Familiarity to Contextual Retrieval","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/vocabulary-audit.en.md","filePath":"public/downloads/worksheets/vocabulary-audit.en.md","lastUpdated":1795488252000}'),n={name:"public/downloads/worksheets/vocabulary-audit.en.md"};function i(o,t,l,s,c,h){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="vocabulary-evidence-card-from-card-familiarity-to-contextual-retrieval" tabindex="-1">Vocabulary Evidence Card: From Card Familiarity to Contextual Retrieval <a class="header-anchor" href="#vocabulary-evidence-card-from-card-familiarity-to-contextual-retrieval" aria-label="Permalink to &quot;Vocabulary Evidence Card: From Card Familiarity to Contextual Retrieval&quot;">​</a></h1><p>Copy this card into a private note for one real topic or task. Do not include passwords, customer records, unpublished documents, exam answers, medical privacy, or unauthorised third-party material. A final word list may be public without making source material, recordings, and feedback public.</p><h2 id="_1-define-the-task-and-evidence-conditions" tabindex="-1">1. Define the Task and Evidence Conditions <a class="header-anchor" href="#_1-define-the-task-and-evidence-conditions" aria-label="Permalink to &quot;1. Define the Task and Evidence Conditions&quot;">​</a></h2><h3 id="vocabulary-evidence-yyyy-mm-dd" tabindex="-1">Vocabulary Evidence - YYYY-MM-DD <a class="header-anchor" href="#vocabulary-evidence-yyyy-mm-dd" aria-label="Permalink to &quot;Vocabulary Evidence - YYYY-MM-DD&quot;">​</a></h3><p>Real situation and audience:<br> Task: listen / read / speak / write / exam / hand over<br> Material, version, and source:<br> What should another person understand, decide, or complete?<br> Time and length limit:<br> Permitted captions / dictionary / translation / search / AI / people:<br> Privacy, copyright, confidentiality, exam, and expert boundary:<br> First-encounter date:<br> Parallel-task date:</p><p>The target is not &quot;items added.&quot; It is understanding, choosing, and retrieving under these conditions.</p><h2 id="_2-preserve-a-no-lookup-first-encounter" tabindex="-1">2. Preserve a No-Lookup First Encounter <a class="header-anchor" href="#_2-preserve-a-no-lookup-first-encounter" aria-label="Permalink to &quot;2. Preserve a No-Lookup First Encounter&quot;">​</a></h2><p>First-encounter start/end time:<br> Gist, relationships, and next step before lookup:<br> Details understood with confidence:<br> Places that required guessing:<br> Sentence or timestamp where meaning stopped:<br> Sense/expression I tried then:<br> Raw retelling, recording, cloze, or draft location:<br> Did it complete the real task? yes / partly / no</p><p>First check whether the barrier is lexical. Sound segmentation, syntax, background, layout, and attention can also break a sentence.</p><h2 id="_3-build-an-unknown-item-decision-queue" tabindex="-1">3. Build an Unknown-Item Decision Queue <a class="header-anchor" href="#_3-build-an-unknown-item-decision-queue" aria-label="Permalink to &quot;3. Build an Unknown-Item Decision Queue&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Word/chunk</th><th>Task impact</th><th>Decision</th><th>Basis then</th><th>Next check</th></tr></thead><tbody><tr><td></td><td>blocking / important / minor / none</td><td>skip / infer / quick lookup / learn / expert check</td><td></td><td></td></tr></tbody></table><p>Five to eight chunks entering deliberate learning:<br> Items to skip and why:<br> Items requiring a primary source or expert:<br> Items deferred because of capacity:</p><h2 id="_4-record-eight-dimensions-for-each-valuable-chunk" tabindex="-1">4. Record Eight Dimensions for Each Valuable Chunk <a class="header-anchor" href="#_4-record-eight-dimensions-for-each-valuable-chunk" aria-label="Permalink to &quot;4. Record Eight Dimensions for Each Valuable Chunk&quot;">​</a></h2><p>Copy once per chunk:</p><p>Word/chunk:<br> Task function:<br> Form, inflection, and derivation:<br> Sound, stress, and connected speech:<br> Current sense in my own words:<br> Common collocation or sentence slot:<br> Grammatical behaviour:<br> Register, politeness, stance, and identity:<br> Concept, referent, version, or domain boundary:<br> Current retrieval time and required cue:<br> One near-synonym/counterexample and difference:</p><p>Do not copy an entire dictionary page to fill the fields. Keep only what can change understanding or use in this task.</p><h2 id="_5-verify-sense-collocation-and-source" tabindex="-1">5. Verify Sense, Collocation, and Source <a class="header-anchor" href="#_5-verify-sense-collocation-and-source" aria-label="Permalink to &quot;5. Verify Sense, Collocation, and Source&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item to check</th><th>My candidate</th><th>Source, version, location</th><th>Result</th><th>Unknown</th></tr></thead><tbody><tr><td>Sense</td><td></td><td></td><td></td><td></td></tr><tr><td>Pronunciation</td><td></td><td></td><td></td><td></td></tr><tr><td>Collocation</td><td></td><td></td><td></td><td></td></tr><tr><td>Register</td><td></td><td></td><td></td><td></td></tr><tr><td>Technical/institutional concept</td><td></td><td></td><td></td><td></td></tr></tbody></table><p>Why this dictionary/corpus fits this task:<br> Primary document / standard / code location:<br> Check date:<br> Who decides the high-risk term:<br> What evidence would change the decision:</p><p>AI examples and explanations are candidates, not sources. Frequency or confident model tone cannot decide high-risk terminology.</p><h2 id="_6-design-unaided-retrieval" tabindex="-1">6. Design Unaided Retrieval <a class="header-anchor" href="#_6-design-unaided-retrieval" aria-label="Permalink to &quot;6. Design Unaided Retrieval&quot;">​</a></h2><p>Real intention or situational cue:<br> Prompt allowed on first attempt:<br> Prompt removed next time:<br> Target retrieval time:<br> Speaking task:<br> Writing task:<br> Person / time / topic / tone / mode to change:</p><table tabindex="0"><thead><tr><th>Attempt</th><th>Condition</th><th>Actual expression</th><th style="text-align:right;">Retrieval time</th><th>Result</th></tr></thead><tbody><tr><td>Original context</td><td>Answer hidden</td><td></td><td style="text-align:right;"></td><td></td></tr><tr><td>Changed context</td><td>Source sentence removed</td><td></td><td style="text-align:right;"></td><td></td></tr><tr><td>Real task</td><td>Audience and consequence</td><td></td><td style="text-align:right;"></td><td></td></tr></tbody></table><p>Reproducing only the complete source sentence is not transfer.</p><h2 id="_7-ask-a-real-reader-or-listener-to-check-it" tabindex="-1">7. Ask a Real Reader or Listener to Check It <a class="header-anchor" href="#_7-ask-a-real-reader-or-listener-to-check-it" aria-label="Permalink to &quot;7. Ask a Real Reader or Listener to Check It&quot;">​</a></h2><p>Meaning retold by the reader/listener:<br> Relationship, certainty, and next step they heard:<br> Place that required guessing or confirmation:<br> Did the lexical choice change fact or responsibility?<br> Task completed? yes / partly / no<br> Real response or execution result:</p><table tabindex="0"><thead><tr><th>Feedback</th><th>Type</th><th>Decision</th><th>Reason</th><th>Used in parallel task?</th></tr></thead><tbody><tr><td></td><td>necessary repair / acceptable variant / register / style</td><td>accept / partly / reject / defer</td><td></td><td></td></tr></tbody></table><h2 id="_8-record-the-error-and-minimum-repair" tabindex="-1">8. Record the Error and Minimum Repair <a class="header-anchor" href="#_8-record-the-error-and-minimum-repair" aria-label="Permalink to &quot;8. Record the Error and Minimum Repair&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Error sample</th><th>Type</th><th>Likely gap</th><th>Change only this</th><th>Retest condition</th></tr></thead><tbody><tr><td></td><td>form / sound / sense / collocation / grammar / register / slow retrieval / transfer</td><td></td><td></td><td></td></tr></tbody></table><p>Chunks correct on cards but failed in the task:<br> Chunks heard but not written:<br> Chunks read but not heard:<br> Acceptable variation mislabelled as error:<br> Items needing a split card, lower volume, or more background:</p><h2 id="_9-record-ai-and-tool-use" tabindex="-1">9. Record AI and Tool Use <a class="header-anchor" href="#_9-record-ai-and-tool-use" aria-label="Permalink to &quot;9. Record AI and Tool Use&quot;">​</a></h2><p>Tool / model / version and date:<br> First encounter and candidate that existed before use:<br> Request: sense contrast / collocation candidate / cloze / counterexample<br> / audience simulation / error classification / parallel task<br> / other<br> Scope generated or rewritten by the model:<br> Content that may be invented or outdated:<br> Dictionary / corpus / primary source / human verification:<br> What I accepted, rejected, or deferred, and why:<br> Retrieval task after closing the tool:</p><h2 id="_10-test-delayed-retention-and-transfer" tabindex="-1">10. Test Delayed Retention and Transfer <a class="header-anchor" href="#_10-test-delayed-retention-and-transfer" aria-label="Permalink to &quot;10. Test Delayed Retention and Transfer&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Time</th><th>Remove</th><th>Change</th><th>Output</th><th>Result</th></tr></thead><tbody><tr><td>Same day</td><td>Answer and gloss</td><td>Original topic</td><td>Contextual recall</td><td></td></tr><tr><td>Day 1</td><td>Source sentence</td><td>Sentence and people</td><td>Spoken/written retrieval</td><td></td></tr><tr><td>Days 3-7</td><td>Recent cue</td><td>Mode or audience</td><td>Parallel input/output</td><td></td></tr><tr><td>Day 14</td><td>Old cards and feedback</td><td>New topic, same task</td><td>Timed real output</td><td></td></tr><tr><td>Day 30</td><td>All practice prompts</td><td>Real material/consequence</td><td>Full delivery</td><td></td></tr></tbody></table><p>Chunks still retrieved in time:<br> Chunks successful only in the original item:<br> Most frequent returning error:<br> Did the real task require less guessing or rework?</p><h2 id="_11-score-and-decide-what-to-keep" tabindex="-1">11. Score and Decide What to Keep <a class="header-anchor" href="#_11-score-and-decide-what-to-keep" aria-label="Permalink to &quot;11. Score and Decide What to Keep&quot;">​</a></h2><p>Score each item <code>0-2</code>: <code>0=no evidence/not completed</code>, <code>1=cue-dependent or unstable</code>, <code>2=independent under the current condition</code>.</p><table tabindex="0"><thead><tr><th>Item</th><th style="text-align:right;">Same day</th><th style="text-align:right;">Day 7</th><th style="text-align:right;">Day 14</th><th>Evidence reason</th></tr></thead><tbody><tr><td>Recognise it in sound and text</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Judge current sense and task impact</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Use fitting collocation, form, and register</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Retrieve without prompts under time</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Deliver intended meaning to reader/listener</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Transfer after topic, audience, or mode changes</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr></tbody></table><p>Chunks to keep learning and why:<br> Chunks needing a split or new cue:<br> Chunks to archive:<br> Chunks requiring expert verification:<br> One condition to change next cycle:<br> Next review date:</p><p>Related chapters: <a href="https://byoungd.github.io/up/en/threads/part-1/2-vocabulary" target="_blank" rel="noreferrer">Vocabulary: From Familiarity to Retrieval in Real Tasks</a> | <a href="https://byoungd.github.io/up/en/threads/part-1/3-listening" target="_blank" rel="noreferrer">Listening</a> | <a href="https://byoungd.github.io/up/en/threads/part-1/4-reading" target="_blank" rel="noreferrer">Reading</a> | <a href="https://byoungd.github.io/up/en/threads/part-1/5-speaking" target="_blank" rel="noreferrer">Speaking</a> | <a href="https://byoungd.github.io/up/en/threads/part-1/6-writing" target="_blank" rel="noreferrer">Writing</a> | <a href="https://byoungd.github.io/up/en/threads/part-1/7-ai" target="_blank" rel="noreferrer">Learning English with AI</a></p><hr><p>Source: <a href="https://byoungd.github.io/up/en/templates/vocabulary-audit" target="_blank" rel="noreferrer">Still Here</a> · Manuscript updated: 2026-09-02. Content: <a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>.</p>',42)])])}const p=e(n,[["render",i]]);export{b as __pageData,p as default};
